document.addEventListener("DOMContentLoaded", function () {
  const apiUrl = "https://dfes.goa.gov.in/disaster-management/live-calls/data";
  const tableBody = document.querySelector("#fire-data-table tbody");
  const timeHeader = document.querySelector('th[data-column="time"]');

  let tableData = []; // Store fetched data

  // Function to fetch and display data
  async function fetchAndDisplayData() {
    try {
      const response = await fetch(apiUrl);
      if (!response.ok) {
        throw new Error("Failed to fetch data");
      }
      tableData = await response.json();

      // Sort data by time in descending order before rendering
      sortTable("time", "desc");

      // Set the time header's data-order to descending
      timeHeader.setAttribute("data-order", "desc");
    } catch (error) {
      console.error("Error fetching data:", error);
      tableBody.innerHTML = `<tr><td colspan="6">Error loading data</td></tr>`;
    }
  }

  // Function to parse date and time into a valid Date object for sorting
  function parseDateTime(item) {
    const dateStr = item.date || "1970-01-01"; // Default to avoid errors
    const timeStr = item.outtime || "00:00"; // Default time if missing
    return new Date(`${dateStr} ${timeStr}`);
  }

  // Function to render table rows
  function renderTable(data) {
    tableBody.innerHTML = "";
    data.forEach((item) => {
      const time = `<div>${item.date || "-"}</div><div>${item.outtime || "-"}</div>`;
      const description = `${item.description || "-"} near ${item.near || "-"} at ${item.at || "-"}`;
      const row = `
        <tr>
          <td>${item.taluka || "-"}</td>
          <td>${item.village || "-"}</td>
          <td>${item.type || "-"}</td>
          <td>${item.station || "-"}</td>
          <td>${time}</td>
          <td>${description}</td>
        </tr>
      `;
      tableBody.insertAdjacentHTML("beforeend", row);
    });
  }

  // Function to sort table data
  function sortTable(column, order) {
    tableData.sort((a, b) => {
      let valA, valB;

      if (column === "time") {
        // Sort by date-time
        valA = parseDateTime(a);
        valB = parseDateTime(b);
      } else {
        // Sort other columns as strings
        valA = a[column] ? a[column].toString().toLowerCase() : "";
        valB = b[column] ? b[column].toString().toLowerCase() : "";
      }

      return order === "asc" ? (valA > valB ? 1 : -1) : (valA < valB ? 1 : -1);
    });

    renderTable(tableData);
  }

  // Add click event listeners to table headers
  document.querySelectorAll("#fire-data-table thead th").forEach((header) => {
    header.addEventListener("click", function () {
      const column = this.getAttribute("data-column");
      let currentOrder = this.getAttribute("data-order");
      const newOrder = currentOrder === "asc" ? "desc" : "asc";

      // Update the data-order attribute
      this.setAttribute("data-order", newOrder);

      // Sort the table
      sortTable(column, newOrder);
    });
  });

  // Fetch and display data initially (sorted by descending time)
  fetchAndDisplayData();
});
